  return <><FeeHeader title="Fee collections" text="Daily collections broken down by configured payment method."/><Card className="fees-report-filters"><Field label="From"><input type="date" value={from} onChange={e => setFrom(e.target.value)}/></Field><Field label="To"><input type="date" value={to} onChange={e => setTo(e.target.value)}/></Field><Button variant="secondary" onClick={x.load}><RefreshCw/> Refresh</Button></Card><ReportTable title="Fee collections" subtitle={`Collections from ${from} to ${to}.`} x={x} headers={["Date", "Payment method", "Receipts", "Collected", "Allocated", "Unallocated"]} render={r => <><td>{r.paymentDate}</td><td>{r.paymentMethodName || words(r.methodType)}</td><td>{r.receiptCount}</td><td>{money(r.amountMinor)}</td><td>{money(r.allocatedMinor)}</td><td>{money(r.unallocatedMinor)}</td></>}/></>;
