function AgingReport() {
  const [asOf, setAsOf] = useState(today()); const x = useLoad<R[]>(`${B}/reports/aging${query({ asOf })}`, []);
  return <><FeeHeader title="Receivables ageing" text="See how long student fee balances have remained unpaid."/><Card className="fees-report-filters"><Field label="As of"><input type="date" value={asOf} onChange={e => setAsOf(e.target.value)}/></Field><Button variant="secondary" onClick={x.load}><RefreshCw/> Refresh</Button></Card><ReportTable title="Receivables ageing" subtitle={`Ageing as of ${asOf}.`} x={x} headers={["Student / payer", "Current", "1–30 days", "31–60", "61–90", "90+", "Total"]} render={r => { const total = [r.currentMinor, r.days130Minor, r.days3160Minor, r.days6190Minor, r.days90PlusMinor].reduce((n, x) => n + Number(x || 0), 0); return <><td><b>{r.studentName}</b><small>{r.payerName}</small></td><td>{money(r.currentMinor)}</td><td>{money(r.days130Minor)}</td><td>{money(r.days3160Minor)}</td><td>{money(r.days6190Minor)}</td><td>{money(r.days90PlusMinor)}</td><td><b>{money(total)}</b></td></>; }}/></>;
}
function StatementsPage() {
  const refs = useFeeRefs(); const [kind, setKind] = useState("student"), [id, setId] = useState(""), [year, setYear] = useState(""), [term, setTerm] = useState(""), [data, setData] = useState<R | null>(null), [loading, setLoading] = useState(false), [error, setError] = useState("");
  async function run() { if (!id) return; setLoading(true); setError(""); try { const path = kind === "student" ? `${B}/students/${id}/statement${query({ academicYearId: year, termId: term })}` : kind === "payer" ? `${B}/payers/${id}/statement${query({ academicYearId: year, termId: term })}` : `${B}/guardians/${id}/statement${query({ academicYearId: year, termId: term })}`; setData(await get<R>(path)); } catch (e) { setError(errorText(e)); } finally { setLoading(false); } }
  const charges = data?.charges || [], receipts = data?.receipts || [], reductions = data?.reductions || [], ledgerEntries = data?.ledgerEntries || [];
  const subledgerEntries = [...charges.map((r: R) => ({ id: `c:${r.id}`, date: r.date, reference: r.invoiceNumber, description: r.feeCategory || r.description || "School fee charge", debitMinor: r.totalMinor, creditMinor: 0, status: r.status })), ...receipts.map((r: R) => ({ id: `r:${r.id}`, date: r.date, reference: r.receiptNumber, description: `${r.paymentMethod || "Payment"}${r.reference ? ` · ${r.reference}` : ""}`, debitMinor: 0, creditMinor: r.allocatedMinor ?? r.amountMinor, status: r.status })), ...reductions.map((r:R)=>({id:`x:${r.kind}:${r.id}`,date:r.date,reference:r.reference,description:r.kind==="writeoff"?`Fee write-off${r.reason?` · ${r.reason}`:""}`:`Fee credit${r.reason?` · ${r.reason}`:""}`,debitMinor:0,creditMinor:r.amountMinor,status:r.status}))];
  const entries = (ledgerEntries.length ? ledgerEntries : subledgerEntries).sort((a: R, b: R) => String(a.date || "").localeCompare(String(b.date || "")) || String(a.reference || "").localeCompare(String(b.reference || "")));
  let running = Number(data?.openingBalanceMinor || 0); const withBalance = entries.map((r: R) => ({ ...r, balanceMinor: running += Number(r.debitMinor || 0) - Number(r.creditMinor || 0) }));
  return <><FeeHeader title="Fee statements" text="Review student, payer or guardian fee positions using the school-fee subledger reconciled to Ledgerly receivables."/><Card className="fees-report-filters"><Field label="Statement type"><select value={kind} onChange={e => { setKind(e.target.value); setId(""); setData(null); }}><option value="student">Student</option><option value="payer">Payer contact</option><option value="guardian">Guardian</option></select></Field>{kind === "student" ? <Field label="Student"><StudentSelect value={id} onChange={setId} students={refs.students} loading={refs.loading}/></Field> : kind === "payer" ? <Field label="Payer"><RefSelect loading={refs.loading} value={id} onChange={setId} rows={refs.contacts}/></Field> : <Field label="Guardian"><GuardianSelect value={id} onChange={setId} guardians={refs.guardians} loading={refs.loading}/></Field>}<Field label="Academic year"><RefSelect loading={refs.loading} value={year} onChange={setYear} rows={refs.years} label="All years"/></Field><Field label="Term"><RefSelect loading={refs.loading} value={term} onChange={setTerm} rows={refs.terms.filter((r: R) => !year || r.academicYearId === year)} label="All terms"/></Field><Button onClick={() => void run()} disabled={!id || loading}>{loading ? "Loading…" : "View statement"}</Button></Card>{error && <ErrorBox message={error}/>} {data && kind === "guardian" && <Card className="school-table-card"><div className="fees-statement-head"><div><small>Guardian</small><h2>{data.guardian?.contactName || [data.guardian?.firstName, data.guardian?.lastName].filter(Boolean).join(" ") || "Guardian statement"}</h2></div><div><small>Unallocated payer credit</small><strong>{money(data.unallocatedCreditMinor)}</strong></div></div>{data.students?.length ? <StatementTable title="Guardian fee statement" subtitle={data.guardian?.contactName || [data.guardian?.firstName, data.guardian?.lastName].filter(Boolean).join(" ") || "Guardian"} rows={data.students} headers={["Student","Relationship","Billed","Paid","Credits / write-offs","Balance"]} render={(r:R)=><><td><b>{r.name}</b><small>{r.admissionNumber || r.studentNumber}</small></td><td>{words(r.relationship)}</td><td>{money(r.balance?.billedMinor)}</td><td>{money(r.balance?.paidMinor)}</td><td>{money(Number(r.balance?.creditedMinor || 0) + Number(r.balance?.writtenOffMinor || 0))}</td><td><b>{money(r.balance?.balanceMinor)}</b></td></>}/> : <EmptyState title="No linked students" description="This guardian has no linked student fee accounts."/>}</Card>} {data && kind !== "guardian" && <Card className="school-table-card"><div className="fees-statement-head"><div><small>Account</small><h2>{data.student?.name || data.payer?.name || data.student?.studentName || "Fee statement"}</h2><small>{data.period ? [data.period.academicYearName, data.period.termName].filter(Boolean).join(" · ") : ""}</small></div><div><small>Closing balance</small><strong>{money(data.summary?.balanceMinor)}</strong></div></div><div className="fees-summary-list"><span><small>Opening</small><b>{money(data.openingBalanceMinor)}</b></span><span><small>Billed</small><b>{money(data.summary?.billedMinor)}</b></span><span><small>Paid</small><b>{money(data.summary?.paidMinor)}</b></span><span><small>Credits</small><b>{money(data.summary?.creditedMinor)}</b></span><span><small>Write-offs</small><b>{money(data.summary?.writtenOffMinor)}</b></span></div>{withBalance.length ? <StatementTable title="School fee statement" subtitle={data.student?.name || data.payer?.name || data.student?.studentName || "Fee account"} rows={withBalance} headers={["Date","Reference","Description","Charge","Payment","Running balance"]} render={(r:R)=><><td>{r.date}</td><td>{r.reference || "—"}</td><td>{r.description}<small><Status value={r.status}/></small></td><td>{r.debitMinor ? money(r.debitMinor) : "—"}</td><td>{r.creditMinor ? money(r.creditMinor) : "—"}</td><td><b>{money(r.balanceMinor)}</b></td></>}/> : <EmptyState title="No statement entries" description="No fee charges or receipts were found for this selection."/>}</Card>}</>;
}

function StatementTable({ title, subtitle = "", rows, headers, render, pageSize = 20 }: { title: string; subtitle?: string; rows: R[]; headers: string[]; render: (r: R) => ReactNode; pageSize?: number }) {
  const [page, setPage] = useState(1), [elementId] = useState(() => `statement-${crypto.randomUUID()}`);
  const pages = Math.max(1, Math.ceil(rows.length / pageSize)), safePage = Math.min(page, pages), start = (safePage - 1) * pageSize, visible = rows.slice(start, start + pageSize);
  useEffect(() => { setPage(1); }, [rows]);
  return <><div className="report-tools"><span className="report-tools__meta">{rows.length} row{rows.length === 1 ? "" : "s"} · {pageSize} per page</span><div className="report-tools__actions"><Button variant="secondary" onClick={() => downloadTableCsv(elementId, title)}><FileSpreadsheet size={15}/> Export CSV</Button><Button variant="secondary" onClick={() => printFeeReportElement(elementId, title, subtitle)}><Printer size={15}/> Print</Button></div></div><TableWrap><table><thead><tr>{headers.map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{visible.map((r, i) => <tr key={r.studentId || r.id || `${start+i}`}>{render(r)}</tr>)}</tbody></table></TableWrap><div className="report-pagination"><span>Showing {start + 1}–{Math.min(start + pageSize, rows.length)} of {rows.length}</span><Pagination page={safePage} pages={pages} onChange={setPage}/></div><div className="report-export-source" id={elementId}><table><thead><tr>{headers.map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map((r, i) => <tr key={r.studentId || r.id || `all-${i}`}>{render(r)}</tr>)}</tbody></table></div></>;
}
function ReportTable({ title, subtitle = "", x, headers, render, pageSize = 20 }: { title: string; subtitle?: string; x: { data: R[]; loading: boolean; error: string; load: () => Promise<void> }; headers: string[]; render: (r: R) => ReactNode; pageSize?: number }) {
  const [page, setPage] = useState(1), [elementId] = useState(() => `report-${crypto.randomUUID()}`);
  const pages = Math.max(1, Math.ceil(x.data.length / pageSize)), safePage = Math.min(page, pages), start = (safePage - 1) * pageSize, visible = x.data.slice(start, start + pageSize);
  useEffect(() => { setPage(1); }, [x.data]);
  return <Card className="school-table-card">{x.loading ? <Spinner/> : x.error ? <ErrorBox message={x.error} retry={x.load}/> : x.data.length ? <><div className="report-tools"><span className="report-tools__meta">{x.data.length} row{x.data.length === 1 ? "" : "s"} · {pageSize} per page</span><div className="report-tools__actions"><Button variant="secondary" onClick={() => downloadTableCsv(elementId, title)}><FileSpreadsheet size={15}/> Export CSV</Button><Button variant="secondary" onClick={() => printFeeReportElement(elementId, title, subtitle)}><Printer size={15}/> Print</Button></div></div><TableWrap><table><thead><tr>{headers.map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{visible.map((r, i) => <tr key={r.studentId || r.id || `${start + i}`}>{render(r)}</tr>)}</tbody></table></TableWrap><div className="report-pagination"><span>Showing {start + 1}–{Math.min(start + pageSize, x.data.length)} of {x.data.length}</span><Pagination page={safePage} pages={pages} onChange={setPage}/></div><div className="report-export-source" id={elementId}><table><thead><tr>{headers.map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{x.data.map((r, i) => <tr key={r.studentId || r.id || `all-${i}`}>{render(r)}</tr>)}</tbody></table></div></> : <EmptyState title="No report data" description="No records match the selected filters."/>}</Card>;
}
function SimpleReasonModal({ title, close, run }: { title: string; close: () => void; run: (p: { postingDate: string; reason: string }) => Promise<void> }) {
  const [date, setDate] = useState(today()), [reason, setReason] = useState(""), [busy, setBusy] = useState(false), [error, setError] = useState(""); async function save(e: FormEvent) { e.preventDefault(); setBusy(true); try { await run({ postingDate: date, reason }); close(); } catch (e) { setError(errorText(e)); } finally { setBusy(false); } }
  return <Modal title={title} onClose={close} locked={busy}><form onSubmit={save}><div className="modal-body form-grid"><Field label="Posting date"><input type="date" value={date} onChange={e => setDate(e.target.value)} required/></Field><div className="school-field-full"><Field label="Reason"><textarea value={reason} onChange={e => setReason(e.target.value)} required/></Field></div>{error && <div className="school-field-full"><Notice tone="danger">{error}</Notice></div>}</div><div className="modal-actions"><Button type="button" variant="ghost" onClick={close}>Cancel</Button><Button variant="danger" disabled={busy}>{busy ? "Working…" : "Confirm reversal"}</Button></div></form></Modal>;
}
